export interface ICategory {
	name: string
	typeValue: string
	contentType: ContentType
	folder: string
	collapsed?: boolean
	// Template note new notes copy; unset = none.
	template?: string
}

export interface IStatsTop {
	kind: 'category' | 'property' | 'platform'
	// Top key shapes: category Type value, property name as written, or platform id ('playstation').
	key: string
}

export interface IStatsSettings {
	watchTime: boolean
	tops: IStatsTop[]
}

export interface ISortState {
	key: string
	asc: boolean
}

export type TitleLanguage = 'english' | 'romaji' | 'native'

export interface ILibrarySettings {
	categories: ICategory[]
	// Parent of each category's English subfolder (Library/Movies); '' = vault root.
	libraryFolder: string
	omdbApiKey: string
	googleBooksApiKey: string
	rawgApiKey: string
	comicVineApiKey: string
	anilistToken: string
	malClientId: string
	malClientSecret: string
	malTokens: MalTokens | null
	// Last pushed progress/rating per note; the auto-push skips notes still showing them.
	malEcho: Record<string, { p: string; r: number }>
	malStats: { anime: number; manga: number; updated: number } | null
	// Last full import; the hourly check reimports once a day.
	malLastImport: number
	anilistLastImport: number
	kitsuTokens: KitsuTokens | null
	traktTokens: TraktTokens | null
	traktEcho: Record<string, TraktEcho>
	traktLastImport: number
	// Last pushed progress/rating per note; the auto-push skips notes still showing them.
	kitsuEcho: Record<string, { p: string; r: number }>
	kitsuLastImport: number
	// Category typeValue manga imports use; empty until the first import creates one.
	malMangaType: string
	psnTokens: PsnTokens | null
	psnStats: PsnStats | null
	// SteamID64 from the sign-in window; its session reads the library, no key stored.
	steamId: string
	// Last full read; the daily re-import waits a day from it.
	steamLastImport: number
	nintendoTokens: NintendoTokens | null
	nintendoStats: NintendoStats | null
	nintendoLastImport: number
	// IMDb and Netflix sessions live in the sign-in window's partition.
	watchSites: Record<WatchSite, { connected: boolean; lastImport: number }>
	// What IMDb last got from each title, by IMDb id: rating, watchlist, episode ratings by "season:episode".
	imdbEcho: Record<string, ImdbEcho>
	// The thumb Netflix last got for a title, by Netflix id: 1 down, 2 up, 3 way up.
	netflixEcho: Record<string, number>
	// per show's Netflix ID: the note's episodes ("season:episode" indexes) Netflix has a viewing of, with that viewing's id
	netflixSeen: Record<string, Record<string, number>>
	// shows put on My List after every episode was unticked here
	netflixListed: number[]
	showRecommendations: boolean
	showUpNext: boolean
	showComingSoon: boolean
	localCovers: boolean
	// anime and manga names: english, romaji or native, the first one a source has
	titleLanguage: TitleLanguage
	// after a library note is deleted, offer to take it off the connected sites
	offerRemoteDelete: boolean
	// Netflix titles deleted here: Netflix keeps them, so its import skips them
	netflixIgnored: number[]
	// adult titles in anime and manga search
	adultTitles: boolean
	comingSoonCollapsed: boolean
	showDiary: boolean
	showProfile: boolean
	airing: Record<string, Airing[]>
	airingChecked: number
	upNextCollapsed: boolean
	// Category Up next shows, by name; empty = all.
	upNextCategory: string
	// Off: not-started titles appear in Up next only.
	upNextInCategories: boolean
	twitchClientId: string
	twitchClientSecret: string
	coverProperty: string
	// Comma-separated source fields to leave out of notes.
	skipFields: string
	tmdbApiKey: string
	sortState: Record<string, ISortState>
	// Per category name: chosen year/genre/country/platform.
	filterState: Record<string, Record<string, string>>
	statsCollapsed: boolean
	stats: IStatsSettings
	enrichMarks: Record<string, string>
}

